INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1532683-ics410', 'stk-ziyad08', 'ICS 410', 'info', '{"desc": "جودة المقرر بشكل عام : عادية\nالسمستر المأخوذ فيه : 202 -online\nالدكتور: Dr. Tarek Helmy EL-Basuny\nالكتاب المستخدم للمقرر : ما استخدمته + السلايدات حقت الدكتور دسمة + كان اول تاشبترين من شرح الدكتور والباقي الطلاب\nمدى فايدته في الناحية التطبيقية : صراحة ما اشوف استفدت منها الا اخلص وحدة من مواد الميجر اليكتف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics-410-programming-languages/120851/2", "user": "Ziyad08", "ts": 1636458133000, "tid": 120851, "pn": 2}}', 1636458133000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ziyad08-ics410', 'stk-ziyad08', 'ICS 410', 'doc', '{"docs": [{"id": "stk-dr-f98298", "n": "Dr. Tarek Helmy El-Basuny", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "online Ics 410 - 202\n\nالتحضير :\nيومي من تيمز\n\nطريقة الشرح :\nمن السلايدات شرح اول تشيترين والباقي الطلاب هم الي يشرحون الى نهاية المنهج وكان عليها 15%\nالكويزات :\nعطانا 5 كوزات طويلة ومافيه وقت كافي لها كله عشان الاونلاين\nالميد تيرم:\nكان متوسط مائل للصعوبة.\n\nالفاينلات :\nنفس الميد تيرم لكني ما عرفت درجتي للأسف. الاختبار كوممبببريييهنسع¤ كل شي جابه\n\nالقريد النهائي:\nc+\n\nالصوت:\nلابأس به واضح ينفهم عليه\n\nإضافات :\nلايوجد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532684-ics410", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-tarek-helmy-el-basuny/98298/25", "user": "Ziyad08", "ts": 1636458528000, "tid": 98298, "pn": 25}}]}', 1636458528000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iaaahbs-ics410', 'stk-iaaahbs', 'ICS 410', 'doc', '{"docs": [{"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 410 Term 162\nالتحضير :\nاول خمسة اسابيع من الترم كان ما يحضر ابد. تقريبا بداية السادس بدأ يحضر و كان التحضير بداية الكلاس. بعد الأسبوع العاشر تقريبا وقف التحضير من جديد 🤪. طبعا فترة التحضير ما كان يهتم بالتأخير ابداً.\n\nطريقة الشرح :\nسلايدات شويتين طوال و ما ينفعوا واجد وقت المذاكرة. طبعا درست مع ذا المدرس ICS 202 من زمان و طريقة شرحه ما تغيرت ابد. بالنسبة لي شرحه اقل من المتوسط بشوية. تحس انه يضيع احيانا بنص الشرح و يخليك تفهي 😕. طبعا يسأل الطلاب الدوافير يساعدوه اذا ما عرف يحل مسألة معينة او يعطينا اياها كسؤال اذا جاوبت عليه تحصل درجة 😁.\n\nالكويزات :\nسهلة و تكون اسألتها من السلايدات + الكتاب. اساسا هو يعلمك الأسئلة اللي بتجي بالكويز او يقول لك كيف بتكون طريقتها فيمديك تستعد لها.\n\nالمياجر:\nبصراحة كنت ضايع وقت المياجر ما ادري من فين اذاكر. بس من بعد الميجر الاول لاحظت ان بعض الاسئلة جت من الاسئلة الموجودة بنهاية الشباتر بالكتاب. بالميجر الثاني ذاكرت من الكتاب و حصل تحسن بالدرجات.\n\nالفاينال :\nذاكرت من الكتاب مع انه طويل. بشكل عام, الكتاب هو افضل مصدر للمذاكرة بهذا الكورس. إقرأ الكتاب بشكل دوري و بتكون امورك بالسليم.\n\nالصوت:\nصوت عادي بس كان يجيب لي النوم و يخليني افهي واجد معه مع اني اجلس بالأمام😕. و الأكسنت الإنجليزي حقه شوية دمار. يخلط عربي مع إنجليزي.\n\nالقريد النهائي:\nC\n\nإضافات:\nبنص الكلاس, يطلب في بعض الاحيان من الطلاب يحلوا مسألة يحسب عليها درجات. طبعا اذا كنت محضر للدرس قبل المحاضرة بتجاوب عليه بسهولة. انا كنت ساحب على ذا الشي بذا الكورس :ninja:. نفس الفكرة كان يطبقها ب ICS 202. شي واحد تغير فيه. لاحظت انه قام ينكت وقت الشرح عن الشرح مع انه نكته شوي سخيفة 🚬.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474533-ics410", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/15", "user": "IAAAHBS", "ts": 1496631486000, "tid": 118619, "pn": 15}}]}', 1496631486000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-ics410', 'stk-cs_scientist', 'ICS 410', 'doc', '{"docs": [{"id": "stk-dr-f118619", "n": "Dr. Emad Ramadan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS410-162\n\nبس بأزيد على كلام اللي كتب عنه قبل إن عماد يجيب اختباراته من شرحه، مرات واجد يجيب نفس الأسئلة مع تغيير بسيط أو بالنص\n\nأظن اللي بيكتب نوت وراه و يذاكرها + يحل أسئلة الكتاب خصوصًا في تشابتر 3 و 4، راح يبدع في المادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474825-ics410", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/emad-ramadan/118619/17", "user": "CS_Scientist", "ts": 1497013176000, "tid": 118619, "pn": 17}}]}', 1497013176000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
